using System;using System.Linq;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;using TMPro;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckPoker.Editor {
// Additive room replacement. Existing table, seats, card/privacy layers and
// dealer route are untouched. Owned restaurant modules supply the architecture.
public static class PokerVenueAuthoring {
 const string Folder="TruckPoker",Models="Assets/Modern Resaturant - building and interior/Models/Prefabs/";
 public static void Upgrade(){var scene=EditorSceneManager.OpenScene(PokerAuthoring.Scene);Install(UnityEngine.Object.FindAnyObjectByType<PokerMatch>());EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();}
 public static void Install(PokerMatch m){if(m.transform.Find("Modeled midnight casino interior")!=null)return;foreach(var path in new[]{"Floor_200x200.prefab","Wall_200x300.prefab","Wall_Doorway_200x300.prefab","Restaurant_Reception_Desk.prefab","Street_Lamp.prefab"})if(AssetDatabase.LoadAssetAtPath<GameObject>(Models+path)==null)throw new InvalidOperationException("Owned casino architectural foundation missing: "+path);
  var root=new GameObject("Modeled midnight casino interior").transform;root.SetParent(m.transform,false);foreach(var r in UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsInactive.Include).Where(r=>r.gameObject.scene==m.gameObject.scene&&(r.name=="Casino architectural wall"||r.name=="Carpeted casino floor")))r.gameObject.SetActive(false);foreach(var text in UnityEngine.Object.FindObjectsByType<TextMeshPro>(FindObjectsInactive.Include).Where(t=>t.gameObject.scene==m.gameObject.scene&&(t.text=="TRUCK POKER"||t.text.Contains("VIRTUAL CHIPS ONLY"))))text.gameObject.SetActive(false);
  var floor=Model(root,"Textured owned modular casino floor","Floor_200x200.prefab",new Vector3(0,-.16f,0),new Vector3(60,.16f,52));foreach(var r in floor.GetComponentsInChildren<Renderer>()){var materials=r.sharedMaterials;for(int i=0;i<materials.Length;i++){string path="Assets/TruckPoker/Materials/Repeated casino floor "+i+".mat";var owned=AssetDatabase.LoadAssetAtPath<Material>(path);if(owned==null){owned=new Material(materials[i]);owned.SetTextureScale("_BaseMap",new Vector2(24,21));if(owned.HasProperty("_BumpMap"))owned.SetTextureScale("_BumpMap",new Vector2(24,21));AssetDatabase.CreateAsset(owned,path);}materials[i]=owned;}r.sharedMaterials=materials;}
  for(int side=-1;side<=1;side+=2){for(int section=-5;section<=5;section++){Model(root,"Modeled casino side panel "+side+" "+section,"Wall_200x300.prefab",new Vector3(side*25,0,section*4.3f),new Vector3(4.3f,9,.32f),side*90);Model(root,"Modeled casino end panel "+side+" "+section,side<0&&section==0?"Wall_Doorway_200x300.prefab":"Wall_200x300.prefab",new Vector3(section*4.3f,0,side*23),new Vector3(4.3f,9,.32f),side>0?180:0);}for(int z=-1;z<=1;z+=2){Model(root,"Owned casino reception station","Restaurant_Reception_Desk.prefab",new Vector3(side*20,0,z*18),new Vector3(5,1.8f,2.2f),side>0?-90:90);Model(root,"Owned warm floor-standing light","Street_Lamp.prefab",new Vector3(side*22,0,z*20),new Vector3(2.5f,7.2f,2.5f));}}
  var roof=Model(root,"Cab-visible modeled coffered ceiling","Floor_200x200.prefab",new Vector3(0,9.2f,0),new Vector3(60,.2f,52));roof.transform.rotation=Quaternion.Euler(180,0,0);foreach(var t in roof.GetComponentsInChildren<Transform>(true))t.gameObject.layer=31;var cameras=m.seats.Select(c=>c.view).Concat(new[]{m.broadcast.view}).ToArray();foreach(var camera in cameras){camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.025f,.016f,.04f);EditorUtility.SetDirty(camera);}m.broadcast.view.cullingMask&=~(1<<31);
  for(int i=0;i<6;i++){float angle=i*Mathf.PI/3;var light=new GameObject("Budgeted warm casino downlight").AddComponent<Light>();light.transform.SetParent(root,false);light.transform.position=new Vector3(Mathf.Sin(angle)*12,8.2f,Mathf.Cos(angle)*10);light.transform.rotation=Quaternion.Euler(90,0,0);light.type=LightType.Spot;light.spotAngle=95;light.range=22;light.intensity=500;light.color=new Color(1,.72f,.42f);light.shadows=LightShadows.None;}
  foreach(var light in UnityEngine.Object.FindObjectsByType<Light>())if(light.type==LightType.Directional)light.intensity=.55f;RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.18f,.13f,.2f);RenderSettings.ambientEquatorColor=new Color(.14f,.1f,.15f);RenderSettings.ambientGroundColor=new Color(.065f,.04f,.07f);
  var sign=new GameObject("Depth-tested casino title").AddComponent<TextMeshPro>();sign.transform.SetParent(root,false);sign.transform.localPosition=new Vector3(0,6.4f,22.5f);sign.font=Resources.Load<SportsBroadcastTheme>("SportsBroadcastTheme").headingFont;sign.text="TRUCK POKER";sign.fontSize=13;sign.enableAutoSizing=false;sign.rectTransform.sizeDelta=new Vector2(38,4);sign.alignment=TextAlignmentOptions.Center;sign.color=SportsBroadcastCanvas.Orange;sign.isOverlay=false;
  var probe=new GameObject("Bounded public-only casino reflection").AddComponent<ReflectionProbe>();probe.transform.SetParent(root,false);probe.transform.localPosition=new Vector3(0,4,0);probe.mode=ReflectionProbeMode.Realtime;probe.refreshMode=ReflectionProbeRefreshMode.OnAwake;probe.timeSlicingMode=ReflectionProbeTimeSlicingMode.AllFacesAtOnce;probe.resolution=128;probe.size=new Vector3(60,12,52);probe.boxProjection=true;probe.cullingMask=~((15<<25)|(1<<5));probe.intensity=.65f;probe.farClipPlane=75;
  SportsScenicGradeAuthoring.Install(m.gameObject,cameras,Folder,-.5f);EditorUtility.SetDirty(m);
 }
 static Transform Model(Transform root,string name,string file,Vector3 position,Vector3 size,float yaw=0){var model=new GameObject(name).transform;model.SetParent(root,false);model.position=position;model.rotation=Quaternion.Euler(0,yaw,0);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(model,Models+file,size,0,file.StartsWith("Floor_")||file.StartsWith("Wall_"),Folder);return model;}
}
}
